# owner: platform
"""Seating rows for a class, ordered by last name."""


def _sort_key(student):
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number, chunk):
    names = " | ".join(item.display_name for item in chunk)
    return f"Row {number}: {names}"


def _number_rows(ordered, seats):
    return [
        _row_line(pos // seats + 1, ordered[pos:pos + seats])
        for pos in range(0, len(ordered), seats)
    ]


# ---
def seating_rows(students, seats):
    """Return one "Row N: ..." line per row of seats."""
    if seats < 1 or not students:
        raise ValueError("need students and a positive seat count")
    ordered = sorted(students, key=_sort_key)
    return _number_rows(ordered, seats)
EOF
cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Arden", "Lia")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Arden, Lia | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([make("Arden", "Lia")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
EOF
